_L4:"precision mediump float;\n#define LOWPREC lowp\n// Uniforms look like they're shared between vertex and fragment shaders in GLSL, so we have to be careful to avoid name clashes\n\nuniform sampler2D gm_BaseTexture;\n\nuniform bool gm_PS_FogEnabled;\nuniform vec4 gm_FogColour;\nuniform bool gm_AlphaTestEnabled;\nuniform float gm_AlphaRefValue;\n\nvoid DoAlphaTest(vec4 SrcColour)\n{\n	if (gm_AlphaTestEnabled)\n	{\n		if (SrcColour.a <= gm_AlphaRefValue)\n		{\n			discard;\n		}\n	}\n}\n\nvoid DoFog(inout vec4 SrcColour, float fogval)\n{\n	if (gm_PS_FogEnabled)\n	{\n		SrcColour = mix(SrcColour, gm_FogColour, clamp(fogval, 0.0, 1.0)); \n	}\n}\n\n#define _YY_GLSLES_ 1\n// Shader de fragmento: sh_fnaf_3d.fsh\nvarying vec2 v_vTexcoord;\nvarying vec4 v_vColour;\n\nuniform float distortion; \n\nvoid main() {\n    // 1. Centramos las coordenadas (-0.5 a 0.5)\n    vec2 uv = v_vTexcoord - 0.5;\n\n    // 2. LA MAGIA DE FNAF: Calculamos la profundidad basada en el eje X\n    // Cuanto más a la izquierda o derecha mires, mayor es la curva\n    float depth = uv.x * uv.x; \n\n    vec2 distorted_uv;\n    \n    // 3. Comprime la altura (eje Y) en los bordes de la pantalla\n    distorted_uv.y = uv.y * (1.0 + depth * distortion);\n    \n    // 4. Curva ligeramente la anchura (eje X) para hacer el cilindro perfecto\n    distorted_uv.x = uv.x * (1.0 + depth * (distortion * 0.15));\n\n    // 5. Volvemos a las coordenadas normales (0.0 a 1.0)\n    distorted_uv += 0.5;\n\n    // 6. Si se sale de la textura, pintamos negro oscuro\n    if (distorted_uv.x < 0.0 || distorted_uv.x > 1.0 || distorted_uv.y < 0.0 || distorted_uv.y > 1.0) {\n        gl_FragColor = vec4(0.0, 0.0, 0.0, 1.0);\n    } else {\n        gl_FragColor = v_vColour * texture2D(gm_BaseTexture, distorted_uv);\n    }\n}\n",
